SceneObjects::SceneObjects(ScriptSession& session,SceneAssets& assets,Log& log) : assets_(assets),session_(session) {
    for(auto& [id,unit]:session.units())if(!unit->model.empty())assets.model(unit->model,log);for(auto& [id,item]:session.items())if(!item->model.empty())assets.model(item->model,log);for(unsigned i=0;i<16;++i){auto suffix=(i<10?"0":"")+std::to_string(i);assets.image("ReplaceableTextures\\TeamColor\\TeamColor"+suffix+".blp");assets.image("ReplaceableTextures\\TeamGlow\\TeamGlow"+suffix+".blp");}
    for(auto& [id,d]:session.destructables()){assets.model(d->model,log);if(d->replacement)assets.image(d->texture);}
    auto& world=*session.world();auto& archives=assets.resources();SourceSettings settings;settings.load(archives,"UI\\MiscData.txt");if(auto overlay=archives.readCandidates({"war3mapMisc.txt"},ArchiveScope::Map))settings.parse(overlay->bytes);auto fade=settings.value("Occlusion","OccluderFadeTime","300");size_t consumed=0;auto fadeMs=std::stof(fade,&consumed);if(consumed!=fade.size() || !std::isfinite(fadeMs) || fadeMs<0 || fadeMs>60000)throw std::runtime_error("Invalid occlusion fade time");occlusionFade_=fadeMs/1000.;std::stringstream colors(settings.value("Occlusion","OccluderColor","128,255,255,255"));for(auto& component:occlusionColor_){std::string part;if(!std::getline(colors,part,','))throw std::runtime_error("Invalid occlusion color");size_t at=0;int value=std::stoi(part,&at);if(at!=part.size() || value<0 || value>255)throw std::runtime_error("Invalid occlusion color");component=unsigned(value);}std::string extra;if(std::getline(colors,extra,','))throw std::runtime_error("Invalid occlusion color");auto bytes=archives.readCandidates({"war3map.doo"},ArchiveScope::Map);if(!bytes)return;
    auto destructables=definitions(archives,"Units\\DestructableData.slk","Units\\DestructableMetaData.slk","war3map.w3b",false,log),doodads=definitions(archives,"Doodads\\Doodads.slk","Doodads\\DoodadMetaData.slk","war3map.w3d",true,log);Binary b(bytes->bytes);b.expect(tag("W3do"));auto version=b.u32();b.u32();if(version!=7 && version!=8)throw std::runtime_error("Unsupported classic placed DOO version");auto count=b.count(version==7?42:50,200000);placed_.reserve(count);auto raw=[&]{auto code=b.take(4);return ObjectData::code({reinterpret_cast<const char*>(code.data()),4});};
    auto add=[&](SceneObject object,int variation,bool solid){assets.check();auto found=destructables.find(object.type);bool destructable=found!=destructables.end();const SourceTable::Row* row=destructable?&found->second:nullptr;if(!row){auto d=doodads.find(object.type);if(d!=doodads.end())row=&d->second;}if(!row)throw std::runtime_error("Unknown placed source object: "+ObjectData::name(object.type));auto path=value(*row,"file");if(path.empty() || path=="_")throw std::runtime_error("Placed object has no source model: "+ObjectData::name(object.type));auto name=placedModel(*row,variation);object.model=&assets.model(name,log);object.radius=object.model->radius()*std::max({object.scale[0],object.scale[1],object.scale[2]});object.occlusionHeight=std::max(0.f,object.source?object.source->occluder:number(*row,"occH"))*object.scale[2];object.occlusionRadius=std::clamp(object.source?object.source->radius:object.radius,16.f,512.f);object.replacement=unsigned(number(*row,"texID"));object.texture=value(*row,"texFile");if(object.replacement && !object.texture.empty() && object.texture!="_"){if(!object.texture.ends_with(".blp") && !object.texture.ends_with(".tga"))object.texture+=".blp";assets.image(object.texture);}else object.replacement=0;
        if(solid && !object.dead && !object.source){auto pathTex=value(*row,"pathTex");if(!pathTex.empty() && pathTex!="_" && pathTex!="none"){auto& image=assets.image(pathTex);if(image.width>256 || image.height>256)throw std::runtime_error("Placed pathing texture exceeds footprint budget");float cosine=std::cos(object.angle),sine=std::sin(object.angle);for(unsigned y=0;y<image.height;++y)for(unsigned x=0;x<image.width;++x)if((image.pixels[y*image.width+x]>>16)&255){float dx=(float(x)+.5f-float(image.width)/2)*32,dy=(float(image.height)/2-float(y)-.5f)*32;world.block(object.position[0]+dx*cosine-dy*sine,object.position[1]+dx*sine+dy*cosine);}}}
        append(std::move(object));};
    for(unsigned i=0;i<count;++i){SceneObject object;object.doodadIndex=i;object.type=raw();int variation=b.i32();for(auto& v:object.position)v=b.f32();object.angle=b.f32();for(auto& v:object.scale){v=b.f32();if(v<=0 || v>100)throw std::runtime_error("Invalid DOO model scale");}auto flags=b.u8(),life=b.u8();object.visible=(flags&2)!=0;object.dead=life==0;if(version==8){b.u32();auto sets=b.count(4,65536);for(unsigned set=0;set<sets;++set)b.take(size_t(b.count(8,65536))*8);}b.i32();auto handle=session.placedDestructable(i);if(handle){auto live=session.destructables().find(handle);if(live==session.destructables().end())continue;object.source=live->second;object.handle=handle;liveHandles_.insert(handle);}add(std::move(object),variation,flags!=0);}
    b.u32();auto terrain=b.count(16,65536);for(unsigned i=0;i<terrain;++i){SceneObject object;object.doodadIndex=size_t(count)+i;object.type=raw();b.u32();auto x=b.u32(),y=b.u32();if(x>=world.data().terrain.width || y>=world.data().terrain.height)throw std::runtime_error("Terrain doodad outside map");object.position={world.data().terrain.origin[0]+x*128,world.data().terrain.origin[1]+y*128,0};auto& c=world.data().terrain.corners[y*world.data().terrain.width+x];object.position[2]=(float(c.ground)-8192)/4+(int(c.cliff&15)-2)*128;add(std::move(object),0,true);}b.finish();
    log.write("scene_placements="+std::to_string(placed_.size())+" blocks="+std::to_string(blocks_.size())+" units="+std::to_string(session.units().size()));
}
void SceneObjects::append(SceneObject object) {if(placed_.size()>=400000)throw std::runtime_error("Scene placement count exceeds budget");auto index=placed_.size();auto& block=blocks_[{int(std::floor(object.position[0]/2048)),int(std::floor(object.position[1]/2048))}];float neutral=object.position[2]-(object.source?object.source->deformationBase:0);for(int sign:{-1,1})block.first.add(object.position[0]+sign*object.radius,object.position[1]+sign*object.radius,neutral+sign*object.radius);block.second.push_back(index);soundCandidates_[object.model].push_back(index);placed_.push_back(std::move(object));}
float SceneObjects::objectHeight(const SceneObject& object,bool affected) const {float neutral=object.position[2]-(object.source?object.source->deformationBase:0);return neutral+(affected?session_.world()->deformation(object.position[0],object.position[1]):0);}
bool SceneObjects::deformationAffected(const SceneBounds& bounds) const {auto& world=*session_.world();auto& t=world.data().terrain;float maxX=t.origin[0]+float(t.width-1)*128,maxY=t.origin[1]+float(t.height-1)*128;if(bounds.low[0]<t.origin[0] || bounds.low[1]<t.origin[1] || bounds.high[0]>maxX || bounds.high[1]>maxY)return true;return world.deformationIntersects(bounds.low[0],bounds.low[1],bounds.high[0],bounds.high[1]);}
void SceneObjects::sync() {if(liveRevision_==session_.destructableRevision())return;bool pending=false;for(auto& [id,d]:session_.destructables())if(!liveHandles_.contains(id)){auto model=assets_.cachedModel(d->model);if(!model || (d->replacement && !assets_.cachedTexture(d->texture))){pending=true;continue;}SceneObject object;object.doodadIndex=d->doodadIndex;object.type=d->type;object.handle=id;object.source=d;object.position={std::bit_cast<float>(d->position.x.bits()),std::bit_cast<float>(d->position.y.bits()),d->z};object.scale=d->scale;object.angle=d->angle;object.radius=model->radius()*std::max({d->scale[0],d->scale[1],d->scale[2]});object.occlusionHeight=std::max(0.f,d->occluder)*d->scale[2];object.occlusionRadius=std::clamp(d->radius,16.f,512.f);object.model=model;object.replacement=d->replacement;object.texture=d->texture;append(std::move(object));liveHandles_.insert(id);}if(!pending)liveRevision_=session_.destructableRevision();}
void SceneObjects::occlude(const std::array<float,3>& eye,const DirectX::XMMATRIX& vp,const TerrainScene* terrain){
    ++occlusionFrame_;if(!occlusionEnabled_ || !session_.occlusionEnabled() || !session_.localPlayer())return;for(float value:eye)if(!std::isfinite(value) || std::abs(value)>1e9f)return;auto local=*session_.localPlayer();auto& world=*session_.world();bool deforming=world.deformationBound()>0;
    for(auto& [id,unit]:session_.units()){if(unit->removing || unit->hidden() || std::bit_cast<float>(unit->life.bits())<=0 || !session_.unitVisibleTo(id,local))continue;float x=std::bit_cast<float>(unit->x.bits()),y=std::bit_cast<float>(unit->y.bits());if(!std::isfinite(x) || !std::isfinite(y) || std::abs(x)>1e9f || std::abs(y)>1e9f)continue;float z=(terrain?terrain->unitHeight(x,y,pathMovement(unit->movementType)):world.height({unit->x,unit->y}))+unit->displayFlyHeight()+40*unit->displayScale();SceneBounds bounds;float radius=std::max(16.f,unit->collision);for(int sign:{-1,1})bounds.add(x+sign*radius,y+sign*radius,z+sign*radius);if(!bounds.visible(vp))continue;double dx=double(x)-eye[0],dy=double(y)-eye[1],length=dx*dx+dy*dy;if(length<1e-6)continue;auto& mapBounds=world.bounds();double minX=std::bit_cast<float>(mapBounds.minX.bits())-512.,maxX=std::bit_cast<float>(mapBounds.maxX.bits())+512.,minY=std::bit_cast<float>(mapBounds.minY.bits())-512.,maxY=std::bit_cast<float>(mapBounds.maxY.bits())+512.,first=0,last=1;auto clip=[&](double origin,double delta,double low,double high){if(std::abs(delta)<1e-12)return origin>=low && origin<=high;double a=(low-origin)/delta,b=(high-origin)/delta;if(a>b)std::swap(a,b);first=std::max(first,a);last=std::min(last,b);return first<=last;};if(!clip(eye[0],dx,minX,maxX) || !clip(eye[1],dy,minY,maxY))continue;int cx=int(std::floor((eye[0]+dx*first)/2048)),cy=int(std::floor((eye[1]+dy*first)/2048)),endX=int(std::floor((eye[0]+dx*last)/2048)),endY=int(std::floor((eye[1]+dy*last)/2048));auto steps=std::int64_t(std::abs(endX-cx))+std::abs(endY-cy)+1;if(steps>512)continue;int sx=(dx>0)-(dx<0),sy=(dy>0)-(dy<0);double infinity=std::numeric_limits<double>::infinity(),nextX=sx?((sx>0?double(cx+1)*2048:double(cx)*2048)-eye[0])/dx:infinity,nextY=sy?((sy>0?double(cy+1)*2048:double(cy)*2048)-eye[1])/dy:infinity,stepX=sx?2048/std::abs(dx):infinity,stepY=sy?2048/std::abs(dy):infinity;auto visit=++occlusionVisit_;
        for(std::int64_t step=0;step<steps;++step){for(int ox=-1;ox<=1;++ox)for(int oy=-1;oy<=1;++oy){auto block=blocks_.find({cx+ox,cy+oy});if(block==blocks_.end())continue;bool affected=deforming && deformationAffected(block->second.first);for(auto index:block->second.second){auto& object=placed_[index];if(object.occlusionVisit==visit || object.occlusionFrame==occlusionFrame_)continue;object.occlusionVisit=visit;float occlusionHeight=object.source?std::max(0.f,object.source->occluder)*object.scale[2]:object.occlusionHeight;if(occlusionHeight<=0 || (object.source?(object.source->removed || !object.source->visible || object.source->life<=0):(!object.visible || object.dead)))continue;double rx=double(object.position[0])-eye[0],ry=double(object.position[1])-eye[1],t=(rx*dx+ry*dy)/length;if(t<=0 || t>=1)continue;double px=eye[0]+dx*t-object.position[0],py=eye[1]+dy*t-object.position[1];if(px*px+py*py>double(object.occlusionRadius)*object.occlusionRadius)continue;double height=eye[2]+(z-eye[2])*t;float base=objectHeight(object,affected);if(height>=base && height<=base+occlusionHeight)object.occlusionFrame=occlusionFrame_;}}if(cx==endX && cy==endY)break;if(nextX<nextY){cx+=sx;nextX+=stepX;}else{cy+=sy;nextY+=stepY;}}
    }
}
DWORD SceneObjects::tint(SceneObject& object,double now){auto factor=occlusionFade_>0?std::clamp((now-object.fadeStart)/occlusionFade_,0.,1.):1.;float value=std::lerp(object.fadeFrom,object.fadeTo,float(factor)),target=object.occlusionFrame==occlusionFrame_?1.f:0.f;if(target!=object.fadeTo){object.fadeFrom=value;object.fadeTo=target;object.fadeStart=now;if(occlusionFade_<=0)value=target;}auto component=[&](unsigned i){return unsigned(std::clamp(std::lround(std::lerp(255.f,float(occlusionColor_[i]),value)),0l,255l));};return (component(0)<<24)|(component(1)<<16)|(component(2)<<8)|component(3);}
std::pair<D3DMATRIX,std::uint64_t> SceneObjects::soundPose(SceneObject& object,std::uint64_t elapsed,bool affected){
    float z=objectHeight(object,affected);auto world=DirectX::XMMatrixScaling(object.scale[0],object.scale[1],object.scale[2])*DirectX::XMMatrixRotationZ(object.angle)*DirectX::XMMatrixTranslation(object.position[0],object.position[1],z);auto d=object.source;auto visual=session_.doodad(object.doodadIndex);std::uint64_t time=elapsed;std::string animation=object.dead?"Death":"Stand";double start=visual?visual->animationStart:0;if(d){animation=d->animation.empty()?(d->life>0?"Stand":"Death"):d->animation;start=d->animationStart;time=d->initialDead && d->animation.empty()?UINT64_MAX/2:std::uint64_t(d->animationElapsed(double(elapsed)/1000)*1000);}else if(visual && !visual->animation.empty()){animation=visual->animation;time=std::uint64_t(std::max(0.,double(elapsed)-start*1000));}else if(object.dead)time=UINT64_MAX/2;if(!object.model->sequence(animation))object.model->sequence("Stand");if(visual && visual->randomStart==start && visual->randomAnimation==animation && object.model->sequenceDuration())time+=visual->randomPhase%object.model->sequenceDuration();return {sceneMatrix(world),time};
}
size_t SceneObjects::draw(Renderer&,const D3DMATRIX& view,const D3DMATRIX& projection,std::uint64_t elapsed,const std::array<float,3>& eye,const TerrainScene* terrain,const SoundPredicate& hasSound,const SoundConsumer& playSound) {
    sync();++soundFrame_;auto vp=sceneMatrix(view)*sceneMatrix(projection);occlude(eye,vp,terrain);size_t count=0;float padding=session_.world()->deformationBound();for(auto& [cell,block]:blocks_)if(([&]{auto bounds=block.first;bounds.low[2]-=padding;bounds.high[2]+=padding;return bounds.visible(vp);}())){bool affected=padding>0 && deformationAffected(block.first);for(auto i:block.second){auto& object=placed_[i];if(object.source?(object.source->removed || !object.source->visible):!object.visible)continue;float z=objectHeight(object,affected);SceneBounds bounds;for(int sign:{-1,1})bounds.add(object.position[0]+sign*object.radius,object.position[1]+sign*object.radius,z+sign*object.radius);if(!bounds.visible(vp))continue;auto world=DirectX::XMMatrixScaling(object.scale[0],object.scale[1],object.scale[2])*DirectX::XMMatrixRotationZ(object.angle)*DirectX::XMMatrixTranslation(object.position[0],object.position[1],z);if(object.replacement)object.model->replace(object.replacement,assets_.texture(object.texture));auto d=object.source;auto visual=session_.doodad(object.doodadIndex);std::uint64_t time=elapsed;std::string animation=object.dead?"Death":"Stand";double start=visual?visual->animationStart:0;if(d){animation=d->animation.empty()?(d->life>0?"Stand":"Death"):d->animation;start=d->animationStart;time=d->initialDead && d->animation.empty()?UINT64_MAX/2:std::uint64_t(d->animationElapsed(double(elapsed)/1000)*1000);}else if(visual && !visual->animation.empty()){animation=visual->animation;time=std::uint64_t(std::max(0.,double(elapsed)-start*1000));}else if(object.dead)time=UINT64_MAX/2;if(!object.model->sequence(animation))object.model->sequence("Stand");if(visual && visual->randomStart==start && visual->randomAnimation==animation && object.model->sequenceDuration())time+=visual->randomPhase%object.model->sequenceDuration();auto color=session_.indicatorColor(object.handle,tint(object,double(elapsed)/1000));object.model->draw(time,view,projection,sceneMatrix(world),true,color,&object.particles,elapsed);if(color>>24)object.soundVisibleFrame=soundFrame_;++count;}}
    if(hasSound && playSound){auto local=session_.localPlayer().value_or(0);for(auto& [model,indices]:soundCandidates_){if(!model || !hasSound(*model))continue;std::erase_if(indices,[&](size_t index){auto& object=placed_[index];if(!object.source || !object.source->removed)return false;object.sound.reset();return true;});for(auto index:indices){auto& object=placed_[index];if((object.source?(object.source->removed || !object.source->visible):!object.visible) || session_.fog(local).state({jass::Real::fromBits(std::bit_cast<std::uint32_t>(object.position[0])),jass::Real::fromBits(std::bit_cast<std::uint32_t>(object.position[1]))})!=4){object.sound.reset();continue;}if(!object.sound)object.sound=std::make_unique<ModelInstance>();auto [world,time]=soundPose(object,elapsed,padding>0);playSound(*model,*object.sound,time,elapsed,world,object.soundVisibleFrame==soundFrame_);}}}
    return count;
}
